86	/** Fetch a specific sent-share row by shareId for the given account. */
87	async function getSentShare(accessToken: string, shareId: string): Promise<SentShareRow> {
88	  const res = await testFetch(`${API_URL}/shares/sent`, {
89	    headers: { Authorization: `Bearer ${accessToken}` },
90	  });
91	  expect(res.ok).toBe(true);
92	  const data = (await res.json()) as { shares: SentShareRow[] };
93	  const share = data.shares.find((s) => s.shareId === shareId);
94	  if (!share) throw new Error(`sent share ${shareId} not found`);
95	  return share;
96	}
97	
98	// SKIPPED: live-stack reproduction of a blocked fix — see the file header for the
99	// three gaps (A worked-around, B + C real product bugs outside tests/sdk-e2e).
100	describe.skip('File-Share Grant Re-Mint on Scope-Exit Rotation', () => {
101	  let fixture: MultiAccountFixture;
102	
103	  beforeAll(async () => {
104	    // Only alice (the owner performing the rotation) needs the inline seam.
105	    fixture = await createMultiAccountFixture(['alice', 'bob', 'carol'], {
106	      alice: { withInlineGrantRemint: true },
107	    });
108	  });
109	
110	  afterAll(async () => {
111	    if (fixture) await fixture.cleanupAll();
